const cfg = JSON.parse($('Config').first().json.CONFIG_JSON);
const lookbackDays = Math.max(1, Math.ceil(cfg.NEWS_LOOKBACK_HOURS / 24));

const items = cfg.KEYWORDS.map(keyword => {
  const q = `${keyword} when:${lookbackDays}d`;
  const url = `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&hl=en-US&gl=US&ceid=US:en`;
  return { json: { url, keyword } };
});

return items;

const cfg = JSON.parse($('Config').first().json.CONFIG_JSON);
const queries = [];

// Targeted searches per competitor account (public search results only)
for (const acc of cfg.COMPETITOR_ACCOUNTS) {
  if (acc.name) {
    queries.push({ query: `site:twitter.com OR site:x.com "${acc.name}"`, account: acc.name, hint: 'x' });
    queries.push({ query: `site:linkedin.com "${acc.name}"`, account: acc.name, hint: 'linkedin' });
  }
}

// Generic targeted topic searches (section 6 of the brief)
for (const kw of cfg.KEYWORDS) {
  queries.push({ query: `"${kw}" (site:twitter.com OR site:x.com OR site:linkedin.com)`, account: null, hint: 'topic' });
}

return queries.map(q => ({ json: q }));

// RSS Feed Read outputs one item per article, fields: title, link, pubDate, isoDate, contentSnippet
const item = $input.item.json;

function domainOf(url) {
  try { return new URL(url).hostname.replace('www.', ''); } catch (e) { return 'unknown'; }
}

return {
  json: {
    category: 'news',
    title: item.title || 'Untitled',
    url: item.link || item.guid || '',
    platform: 'Google Search / News',
    sourceName: domainOf(item.link || ''),
    publishedDate: item.isoDate || item.pubDate || null,
    snippet: item.contentSnippet || item.content || '',
    engagement: 'Not applicable (news item).'
  }
};

const all = $input.all();
const out = [];

function detectPlatform(url) {
  const u = (url || '').toLowerCase();
  if (u.includes('twitter.com') || u.includes('x.com')) return 'X / Twitter';
  if (u.includes('linkedin.com')) return 'LinkedIn';
  return 'Google Search';
}

for (const item of all) {
  const res = item.json;
  const results = res.items || [];
  for (const r of results) {
    out.push({
      json: {
        category: 'competitor',
        title: r.title || 'Untitled',
        url: r.link,
        platform: detectPlatform(r.link),
        sourceName: r.displayLink || '',
        publishedDate: null,
        snippet: r.snippet || '',
        engagement: 'Engagement data unavailable.'
      }
    });
  }
}

return out;

const cfg = JSON.parse($('Config').first().json.CONFIG_JSON);
const staticData = $getWorkflowStaticData('global');
staticData.seenUrls = staticData.seenUrls || {};

const now = Date.now();
const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;

// Prune old memory entries so it never grows unbounded
for (const url of Object.keys(staticData.seenUrls)) {
  if (now - (staticData.seenUrls[url].reportedAt || 0) > THIRTY_DAYS) {
    delete staticData.seenUrls[url];
  }
}

const all = $input.all().map(i => i.json).filter(i => i.url);

// Deduplicate within this run by URL
const uniqueByUrl = {};
for (const it of all) {
  if (!uniqueByUrl[it.url]) uniqueByUrl[it.url] = it;
}

const fresh = Object.values(uniqueByUrl).filter(it => !staticData.seenUrls[it.url]);

const newsItems = fresh.filter(i => i.category === 'news').slice(0, cfg.MAX_NEWS_RESULTS * 4);
const competitorItems = fresh.filter(i => i.category === 'competitor').slice(0, cfg.MAX_COMPETITOR_RESULTS * 4);

return [{
  json: {
    config: cfg,
    newsItems,
    competitorItems,
    totalNew: newsItems.length + competitorItems.length
  }
}];

const data = $input.item.json;
const cfg = data.config;

const systemPrompt = `You are Nexra's Senior AI & Automation Research Analyst.
Nexra is an AI Automation agency building AI Agents, workflow automation, CRM/sales/marketing automation, and AI-powered systems for B2B and SMB clients.

Your job: analyze the raw search results below and produce a strategic research briefing.

RULES:
- Never invent engagement numbers, dates, authors, or facts. If unavailable, keep the original "engagement" field text as-is.
- Rank competitor content using: Relevance 30%, Engagement 25%, Content Quality 20%, Business Value 15%, Originality 10%.
- Only keep items with an estimated relevance+quality score at or above ${cfg.MIN_RELEVANCE_SCORE} and ${cfg.MIN_QUALITY_SCORE} (out of 10) respectively.
- Return at most ${cfg.MAX_COMPETITOR_RESULTS} competitor items and ${cfg.MAX_NEWS_RESULTS} news items, the strongest ones only. Quality over quantity - return fewer if that's all that qualifies.
- Deduplicate near-identical news stories into a single entry, listing extra sources in "additionalSources".
- Classify each kept item priority as "high", "medium", or "low".
- Generate ${cfg.MAX_CONTENT_OPPORTUNITIES} ORIGINAL Nexra content opportunities inspired by (never copied or paraphrased sentence-by-sentence from) the research. Each needs a unique angle, not just "write about topic X".
- Respond with STRICT JSON ONLY, no markdown fences, no commentary, matching exactly this schema:
{
  "competitorContent": [
    {"title": "", "platform": "", "creator": "", "engagement": "", "whyItMatters": "", "url": "", "priority": "high|medium|low"}
  ],
  "news": [
    {"headline": "", "sourcePlatform": "", "publishedDate": "", "whyItMattersToNexra": "", "contentAngle": "", "url": "", "additionalSources": [], "priority": "high|medium|low"}
  ],
  "contentOpportunities": [
    {"topic": "", "angle": "", "whyItCouldWork": "", "suggestedHook": ""}
  ]
}`;

const userPrompt = `Language for the output text: ${cfg.LANGUAGE}

COMPETITOR / TOPIC SEARCH RESULTS (raw, may include noise - filter aggressively):
${JSON.stringify(data.competitorItems)}

NEWS RESULTS (raw, may include duplicates - group them):
${JSON.stringify(data.newsItems)}`;

return [{
  json: {
    config: cfg,
    systemPrompt,
    userPrompt
  }
}];

const cfg = JSON.parse($('Config').first().json.CONFIG_JSON);
const response = $input.item.json;

let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Unexpected AI response shape: ' + JSON.stringify(response).slice(0, 500));
}

const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse AI JSON output: ' + e.message);
}

parsed.competitorContent = parsed.competitorContent || [];
parsed.news = parsed.news || [];
parsed.contentOpportunities = parsed.contentOpportunities || [];

return [{ json: { config: cfg, result: parsed } }];

const staticData = $getWorkflowStaticData('global');
staticData.seenUrls = staticData.seenUrls || {};
const now = Date.now();

const cfg = JSON.parse($('Config').first().json.CONFIG_JSON);
const result = $input.item.json.result;

for (const c of result.competitorContent) {
  if (c.url) staticData.seenUrls[c.url] = { reportedAt: now };
}
for (const n of result.news) {
  if (n.url) staticData.seenUrls[n.url] = { reportedAt: now };
  for (const extra of (n.additionalSources || [])) {
    if (extra) staticData.seenUrls[extra] = { reportedAt: now };
  }
}

return [{ json: { config: cfg, result } }];

const config = JSON.parse($('Config').first().json.CONFIG_JSON);
const result = $input.item.json.result;
const dateStr = new Date().toISOString().slice(0, 10);

function esc(s) {
  return (s || '').toString().replace(/([_*`\[])/g, '\\$1');
}

const messages = [];

let msg1 = `━━━━━━━━━━━━━━━━━━\n`;
msg1 += `*تقرير ${config.COMPANY_NAME} اليومي للذكاء الاصطناعي*\n`;
msg1 += `━━━━━━━━━━━━━━━━━━\n\n`;
msg1 += `📅 التاريخ: ${dateStr}\n\n`;

if (result.competitorContent.length) {
  msg1 += `🔥 *أفضل محتوى المنافسين*\n\n`;
  result.competitorContent.forEach((c, i) => {
    msg1 += `${i + 1}. ${esc(c.title)}\n`;
    msg1 += `المنصة: ${esc(c.platform)}\n`;
    msg1 += `الناشر: ${esc(c.creator || 'غير معروف')}\n`;
    msg1 += `التفاعل: ${esc(c.engagement)}\n`;
    msg1 += `ليه مهم: ${esc(c.whyItMatters)}\n`;
    msg1 += `المصدر: ${c.url}\n\n---\n\n`;
  });
} else {
  msg1 += `🔥 *أفضل محتوى المنافسين*\nمفيش نتائج تستاهل النهاردة.\n`;
}
messages.push(msg1);

if (result.news.length) {
  let msg2 = `🚨 *أخبار الذكاء الاصطناعي والأتمتة*\n\n`;
  result.news.forEach((n, i) => {
    let entry = `${i + 1}. ${esc(n.headline)}\n`;
    entry += `منصة المصدر: ${esc(n.sourcePlatform)}\n`;
    entry += `تاريخ النشر: ${esc(n.publishedDate || 'غير متاح للنشر.')}\n`;
    entry += `ليه مهم لـ Nexra: ${esc(n.whyItMattersToNexra)}\n`;
    entry += `زاوية محتوى مقترحة: ${esc(n.contentAngle)}\n`;
    entry += `المصدر: ${n.url}\n\n---\n\n`;

    if ((msg2 + entry).length > 3900) {
      messages.push(msg2);
      msg2 = entry;
    } else {
      msg2 += entry;
    }
  });
  messages.push(msg2);
} else {
  messages.push(`🚨 *أخبار الذكاء الاصطناعي والأتمتة*\nمفيش نتائج تستاهل النهاردة.`);
}

if (result.contentOpportunities.length) {
  let msg3 = `💡 *أفكار محتوى مقترحة*\n\n`;
  result.contentOpportunities.forEach((o, i) => {
    msg3 += `${i + 1}. الموضوع: ${esc(o.topic)}\n`;
    msg3 += `الزاوية: ${esc(o.angle)}\n`;
    msg3 += `ليه هتنجح: ${esc(o.whyItCouldWork)}\n`;
    msg3 += `مقترح الافتتاحية (Hook): ${esc(o.suggestedHook)}\n\n`;
  });
  messages.push(msg3);
}

return messages.map(m => ({ json: { telegramText: m } }));

const err = $input.item.json.error || $input.item.json.errorMessage;
let text;

if (err) {
  text = `⚠️ *وكيل أبحاث Nexra - خطأ*\n\nتشغيلة البحث النهاردة واجهت مشكلة ومكملتش:\n\n${(err.message || err).toString().slice(0, 500)}\n\nراجع سجل التنفيذ في n8n للتفاصيل.`;
} else {
  text = `✅ *تقرير Nexra اليومي*\n\nمفيش محتوى منافسين أو أخبار عالي الجودة اجتاز معايير الفلترة النهاردة. الجودة أهم من الكمية - محبعتش حاجة.`;
}

return [{ json: { telegramText: text } }];
